  start+="p = contract.iloc[0]\ny = data['actual_label'].to_numpy()\nscores = data['score'].to_numpy()\nassert scores.shape == y.shape\npositive = y == 1\nnegative = y == 0\n# Supplied threshold protocol preserves probability representation and declared order.\npredictions = [scores >= threshold for threshold in thresholds['threshold']]\ntp_masks = [(y == 1) & pred for pred in predictions]\nfp_masks = [(y == 0) & pred for pred in predictions]\nfn_masks = [(y == 1) & ~pred for pred in predictions]\ntn_masks = [(y == 0) & ~pred for pred in predictions]\n"
